entries[70924] = { ["name"] = "Ewiges Auge der Elune", ["text"] = "Geschmolzene Front\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Stellt im Verlauf von 5 Sek. 120000 Gesundheit und 120000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 5 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Intelligenz und 90 Ausdauer. (1 Min Abklingzeit)\n\"Dieses saftige Kernobst platzt fast vor süßem Geschmack. Nur an der Geschmolzenen Front einsetzbar.\"" }
entries[70925] = { ["name"] = "Ewige Mondbirne", ["text"] = "Geschmolzene Front\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Stellt im Verlauf von 5 Sek. 120000 Gesundheit und 120000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 5 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Beweglichkeit und 90 Ausdauer. (1 Min Abklingzeit)\n\"Verströmt ein himmlisches Aroma. Nur an der Geschmolzenen Front einsetzbar.\"" }
entries[70926] = { ["name"] = "Ewige Mondbeere", ["text"] = "Geschmolzene Front\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Stellt im Verlauf von 5 Sek. 120000 Gesundheit und 120000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 5 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Willenskraft und 90 Ausdauer. (1 Min Abklingzeit)\n\"Diese saftigen Beeren schmecken süß und würzig. Nur an der Geschmolzenen Front einsetzbar.\"" }
entries[70927] = { ["name"] = "Ewige Sonnenfrucht", ["text"] = "Geschmolzene Front\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\nBenutzen: Stellt im Verlauf von 5 Sek. 120000 Gesundheit und 120000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 5 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Stärke und 90 Ausdauer. (1 Min Abklingzeit)\n\"Diese köstliche Frucht ist sowohl saftig als auch verlockend. Nur an der Geschmolzenen Front einsetzbar.\"" }
