entries[70995] = { ["name"] = "Glanzloser Pyropanzerfokus", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Setzt den glanzlosen Pyropanzerfokus auf dem Boden ab. Hält 2 Min. lang an.\n\n\"Ein Fragment von Alysrazars Eierschale. Dieser Fokus kann möglicherweise einen Teil von Alysrazars überschüssiger Kraft absorbieren.\"" }
entries[70996] = { ["name"] = "Glanzloser Rhyolithfokus", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Setzt den glanzlosen Rhyolithfokus auf dem Boden ab. Hält 2 Min. lang an.\n\n\"Ein leichtes, flockiges Material aus den Feuerlanden. Ein heftiger Einschlag von Lord Rhyolith könnte diesen Fokus vielleicht verdichten und somit seine Macht erhöhen.\"" }
